        for(int attempt=0;attempt<5;attempt++){check(GroupMessageRetry.due(attempt,attempt==0?0:at-(attempt==0?0:delays[attempt-1]),at),"initial or elapsed attempt is due");store.markAttempt(scope,message.id,at);JSONObject row=store.find(scope,scope.self,message.id);check(row.getInt("attempts")==attempt+1&&row.getString("id").equals(message.id),"same durable ID across all attempts");if(attempt<4){long expected=at+delays[attempt];check(row.getLong("nextRetryAt")==expected&&!GroupMessageRetry.due(attempt+1,at,expected-1)&&GroupMessageRetry.due(attempt+1,at,expected),"10/30/60/120 seconds measured from actual previous attempt");db.close();db=new Jdbc("automatic-retry.sqlite");store=GroupTextStore.open(db);check(store.find(scope,scope.self,message.id).getInt("attempts")==attempt+1,"restart preserves attempt count");long resumed=expected+90000;check(GroupMessageRetry.due(attempt+1,at,resumed),"offline coalesces one due attempt");at=resumed;}}
        check(!GroupMessageRetry.due(5,at,at+1000000)&&store.find(scope,scope.self,message.id).getLong("nextRetryAt")==0,"five total attempts stops timer");db.close();
        Jdbc ackDb=new Jdbc("automatic-ack.sqlite");GroupTextStore ack=GroupTextStore.open(ackDb);GroupTextWire.Message m=enqueue(ack,18002,"ack stops");ack.markAttempt(scope,m.id,now);ack.acknowledge(scope,new GroupTextWire.Receipt(m.group,m.epoch,m.id,m.sender,bob.pin,m.digest(),now),now);check(ack.pending(scope,now+10000).isEmpty(),"durable per-recipient ACK retires pending retries");ackDb.close();
