    static void publicErrors()throws Exception{
        String secret="PRIVATE_MESSAGE_BODY_AND_ID_ABC123";
        for(Exception failure:Arrays.asList(new JSONException(secret),new SQLException(secret),new GeneralSecurityException(secret),new java.security.cert.CertificateException(secret),new SignatureException(secret),new IllegalStateException(secret),new GroupTextStore.NotAccepted(new SQLException(secret))))check(!GroupTextErrors.message(failure).contains(secret),"provider errors cannot expose private content");
        check(GroupTextErrors.message(new GroupTextStore.RevisionConflict()).equals("Saved message data changed; refresh before editing"),"typed storage conflict has stable public diagnostic");
        check(!GroupTextErrors.message(new IllegalStateException("STORE_REVISION_CONFLICT")).contains("STORE_REVISION_CONFLICT"),"private/provider text cannot impersonate a typed conflict");
    }
