        check(((String)db.rows("SELECT record FROM entries WHERE scope=? AND sender=? AND id=?",scope.key,scope.self,outgoing.id).get(0).get("record")).contains(secret),"failed reads preserve unknown saved data instead of silently resetting it");db.close();
        Jdbc reopen=new Jdbc("malformed-record.sqlite");Exception opening=rejects(()->GroupTextStore.open(reopen),"corrupt pending record prevents restart hydration");check(reopen.closed&&!GroupTextErrors.message(opening).contains(secret),"failed restart closes owner and sanitizes saved-record provider error");
